import hashlib, jwt

def resolve_context(db, jwks, cfg, token, agent_id=None, participants=None):
    try:
        claims = jwt.decode(token, jwks.key_for(token), algorithms=["RS256"],
                            audience=cfg.resource_id, issuer=cfg.issuer)   # audience must be the brain
    except jwt.PyJWTError as e:
        raise Unauthorized(str(e))
    scopes = set(claims.get("scope", "").split())
    pid = map_subject(db, claims["iss"], claims["sub"])      # via ac_id, verified mappings only
    if pid is None:
        raise Unauthorized("no verified principal mapping")
    snap = load_groups(db, pid)                              # flattened ids and snapshot id
    principals = {pid, *snap.group_ids}
    scope = scopes
    if agent_id:
        agent = load_agent(db, agent_id)
        if agent is None or agent.owner != pid:
            raise Unauthorized("agent not owned by caller")
        scope = scope & set(agent.scopes) & user_grants(db, pid)
    for other in participants or []:                         # tricky part: a shared session sees the intersection
        op = map_subject_id(db, other)
        principals &= {op, *load_groups(db, op).group_ids} | {pid}
    if len(principals) > 5000:
        principals = {f"set:{snap.snapshot_id}"}
    acl_v = current_acl_version(db, claims["tenant"])
    psid = hashlib.sha256((",".join(sorted(principals)) + f"|{acl_v}").encode()).hexdigest()
    return RequestContext(claims["tenant"], pid, agent_id, sorted(principals), sorted(scope), acl_v, psid)

