W = dict(F=0.4, C=0.3, L=0.2, B=0.1)
TIE = 0.05

def route(sub, plan, apps):
    live_ok = [a for a in apps if a.has_search and a.budget_left_frac > 0.20]   # keep 20% for sync
    live_only = any(a.live_only for a in apps)                                  # terms-of-service rule
    if live_only and live_ok:
        return RouteDecision(sub, "live", "live-only app", {})
    if not live_ok:
        return RouteDecision(sub, "index", "no live-capable app within budget", {})
    scores = {}
    for p in ("index", "live"):
        F = freshness_fit(p, plan.freshness_hint)        # each 0..1
        C = coverage(p, plan.entities, apps)
        L = latency_norm(p, apps)
        Bu = budget_spent_norm(p, apps)
        scores[p] = W["F"] * F + W["C"] * C - W["L"] * L - W["B"] * Bu
    ranked = sorted(scores, key=scores.get, reverse=True)
    if abs(scores[ranked[0]] - scores[ranked[1]]) < TIE:   # tricky part: near tie fuses both paths
        return RouteDecision(sub, "both", "scores within 0.05", scores)
    return RouteDecision(sub, ranked[0], f"{ranked[0]} scored {scores[ranked[0]]:.2f}", scores)

