import hashlib, json, unicodedata

def norm(q):
    return " ".join(unicodedata.normalize("NFKC", q).lower().split())

def key(ctx, query, filters):
    f = json.dumps(filters, sort_keys=True)
    raw = "|".join([norm(query), ctx.principal_set_id, str(ctx.acl_version), f])
    return f"qc:{ctx.tenant_id}:{ctx.principal_set_id[:12]}:" + hashlib.sha256(raw.encode()).hexdigest()

def cache_get(r, ctx, query, filters):
    v = r.get(key(ctx, query, filters))
    return json.loads(v) if v else None

def cache_put(r, ctx, query, filters, pointers, ttl=300):
    blob = json.dumps(pointers[:10])
    if len(blob) > 2048:
        return                                         # oversize entry: skip, never truncate silently
    k = key(ctx, query, filters)
    pipe = r.pipeline()
    pipe.set(k, blob, ex=ttl)
    for p in pointers[:10]:                            # reverse map: doc id to the keys that hold it
        rk = f"qcr:{ctx.tenant_id}:{p['doc_id']}"
        pipe.sadd(rk, k)
        pipe.expire(rk, ttl * 2)
    pipe.execute()

def invalidate_doc(r, tenant, doc_id):
    rk = f"qcr:{tenant}:{doc_id}"
    keys = r.smembers(rk)
    if keys:
        r.delete(*keys)                                # tricky part: delete every holder of this document
    r.delete(rk)

