WIDEN_ORDER = ["period", "type", "entity"]

def build_scope(ctx, plan, cat, acl, cap=5000):
    terms = list(plan.terms)
    widened = False
    for _ in range(3):
        ids = cat.ids_for(ctx.tenant, terms) & acl.visible(ctx)   # permission AND happens first
        if len(ids) > 0:
            break
        drop = next((t for k in WIDEN_ORDER for t in terms if t.kind == k), None)
        if drop is None:
            return Scope.unscoped()
        terms.remove(drop); widened = True
    capped = len(ids) > cap
    return Scope(sorted(ids)[:cap] if capped else sorted(ids), len(ids), [t.value for t in terms], widened, capped)

