def revise(gw, state, res):
    if state.revisions >= 3 or state.tokens_left < 800:
        return Stop(state.open_sub_questions())
    if res.top_score >= 0.8:
        return Continue()
    out = gw.json(model=SMALL, schema=Revision, prompt=render(res))      # result shown as quoted data
    key = (out.action, res.step_id)
    if key in state.tried:
        return Stop(state.open_sub_questions())
    state.tried.add(key); state.revisions += 1
    return out
